public double sum() {
        double totalVolume = 0;
        for (Shape shape : shapes) {
            totalVolume += shape.area();
        }
        return totalVolume;
    }

public double sum() {
        double totalArea = 0;
        for (Shape shape : shapes) {
            if (shape instanceof Shape) {
                totalArea += shape.area();
            } else {
                throw new RuntimeException("Invalid Shape: Shape does not implement Shape interface");
            }
        }
        return totalArea;
    }

